import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    public static void main(String[] args) throws Exception {
        Method factory;
        try {
            factory = Executors.class.getMethod("newVirtualThreadPerTaskExecutor");
        } catch (NoSuchMethodException notOnJdk21) {
            System.out.println("virtualThreadsAvailable=false, java="
                    + System.getProperty("java.version"));
            return;
        }

        ExecutorService executor = (ExecutorService) factory.invoke(null);
        Semaphore dbPermits = new Semaphore(2);
        AtomicInteger maxInDb = new AtomicInteger();
        AtomicInteger activeInDb = new AtomicInteger();
        List<Future<String>> futures = new ArrayList<>();
        try {
            for (int i = 0; i < 6; i++) {
                int taskId = i;
                Callable<String> task = () -> {
                    boolean virtual = isVirtual(Thread.currentThread());
                    dbPermits.acquire();
                    int now = activeInDb.incrementAndGet();
                    maxInDb.accumulateAndGet(now, Math::max);
                    try {
                        Thread.sleep(30);
                        return "task-" + taskId + ":virtual=" + virtual;
                    } finally {
                        activeInDb.decrementAndGet();
                        dbPermits.release();
                    }
                };
                futures.add(executor.submit(task));
            }
            for (Future<String> future : futures) {
                System.out.println(future.get());
            }
            System.out.println("maxInDb=" + maxInDb.get());
            assert maxInDb.get() <= 2;
        } finally {
            executor.shutdown();
            executor.awaitTermination(1, TimeUnit.SECONDS);
        }
    }

    static boolean isVirtual(Thread thread) {
        try {
            Method method = Thread.class.getMethod("isVirtual");
            return (Boolean) method.invoke(thread);
        } catch (ReflectiveOperationException unavailableBeforeJdk21) {
            return false;
        }
    }
}
